import limited_client as robot, numpy as np
base=np.array(robot.observe()['robot']['joint_positions']);g=[.04,.04]
def run(q,n=4):
 for _ in range(n): robot.step(list(q)+g)
 return robot.observe()['robot']
r=run(base,5); qb=np.array(r['tcp_quaternion_wxyz']); pb=np.array(r['tcp_position']);
def rotvec(q):
 q=q/np.linalg.norm(q)
 if q[0]<0:q=-q
 s=np.linalg.norm(q[1:]);return q[1:]*((2*np.arctan2(s,q[0]))/s) if s>1e-9 else 2*q[1:]
def mul(a,b):
 w,x,y,z=a;v,u,r,s=b
 return np.array([w*v-x*u-y*r-z*s,w*u+x*v+y*s-z*r,w*r-x*s+y*v+z*u,w*s+x*r-y*u+z*v])
J=[]
for j in range(7):
 q=base.copy();q[j]+=.05;r=run(q);qa=np.array(r['joint_positions']);qp=np.array(r['tcp_quaternion_wxyz']);dp=np.array(r['tcp_position'])-pb; dq=mul(qp*np.array([1,-1,-1,-1]),qb); J.append(np.r_[dp,rotvec(dq)]/(qa[j]-base[j]));print(j,round(qa[j]-base[j],3),np.round(J[-1],3));run(base)
print(np.array(J).T.round(3).tolist());print(robot.status())
